{
 "$schema": "urn:semantic-agent-schema:published-language:abstract:v1",
 "$id": "urn:example:sample:summary-broken:v1",
 "title": "要約付きの決めごと",
 "description": "目的と、それを1文で言った要約である。",
 "type": "object",
 "required": [
  "$schema",
  "id",
  "goal"
 ],
 "properties": {
  "$schema": {
   "const": "urn:example:sample:summary-broken:v1"
  },
  "id": {
   "title": "ID",
   "description": "ユースケースを区別する名前である。",
   "x-prompt": {
    "rules": []
   },
   "type": "string",
   "pattern": "^R[0-9]+$"
  },
  "goal": {
   "title": "目的",
   "description": "利用者が果たしたいことである。",
   "x-prompt": {
    "rules": [
     {
      "id": "goal-is-outcome",
      "rule": "利用者が得る結果を書く。",
      "why": "手段を書くと、目的が果たせたかを決められない。",
      "check": "結果を表す名詞句かを見る。",
      "bad": [
       {
        "value": "注文フォームに入力する",
        "note": "利用者の操作（手段）で、得る結果ではない。"
       }
      ],
      "good": [
       {
        "value": "注文した品の受け取り"
       }
      ]
     }
    ]
   },
   "type": "string"
  },
  "summary": {
   "title": "要約",
   "description": "目的を1文で言ったものである。",
   "type": "string",
   "x-prompt": {
    "rules": [
     {
      "id": "summary-matches",
      "rule": "目的に食い違わない1文にする。",
      "why": "要約だけ読んだ人が、違うことを決める。",
      "check": "目的に無いことを書いていないかを見る。",
      "related_fields": [
       "/goal"
      ],
      "bad": [
       {
        "value": "請求書を印刷するための決めごと",
        "related": {
         "/goal": "検証の結果を受け取る",
         "/id": "R9"
        },
        "note": "目的に無い請求書の印刷を書いている。"
       }
      ],
      "good": [
       {
        "value": "検証の結果を受け取るための決めごと",
        "related": {
         "/goal": "検証の結果を受け取る"
        }
       }
      ]
     }
    ]
   }
  }
 }
}
